pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user1, address user2, address ref1, address ref2, uint256 ethAmount) public {
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2);
        vm.assume(ref1 != address(0) && ref2 != address(0) && ref1 != ref2);
        vm.assume(ref1 != user1 && ref2 != user2);
        ethAmount = bound(ethAmount, 0.01 ether, 10 ether);

        // Seed market
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        // User1 and User2 get free kilos
        vm.prank(user1);
        c.getFreeKilo();
        vm.prank(user2);
        c.getFreeKilo();

        // User1 buys drugs with ref1
        vm.deal(user1, ethAmount);
        vm.prank(user1);
        c.buyDrugs{value: ethAmount}();

        // User2 buys drugs with ref2
        vm.deal(user2, ethAmount);
        vm.prank(user2);
        c.buyDrugs{value: ethAmount}();

        // Collect drugs for user1 with ref1, then user2 with ref2
        vm.prank(user1);
        c.collectDrugs(ref1);
        vm.prank(user2);
        c.collectDrugs(ref2);

        // Now call DrugDealer (any address, but let's use a random one)
        c.DrugDealer();

        // The rule: Kilos of user1 and user2 must be consistent with the referral mapping
        // Specifically, after DrugDealer, the sum of Kilos of user1 and user2 should be at least the starting kilos (each got 300)
        uint256 kilosUser1 = c.Kilos(user1);
        uint256 kilosUser2 = c.Kilos(user2);
        assertTrue(kilosUser1 >= 300 && kilosUser2 >= 300);
    }
}

