        vm.assume(ref != address(0) && ref != user);

        // First, seed the market to initialize the contract
        vm.deal(address(this), 1 ether);
        c.seedMarket(1000);

        // Give user some starting kilos
        vm.prank(user);
        c.getFreeKilo();

        // Record user's kilos before DrugDealer
