pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != address(0) && caller2 != address(0));
        vm.assume(caller1 != caller2);

        // Seed the market first
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        // Give free kilos to both callers
        vm.prank(caller1);
        c.getFreeKilo();
        vm.prank(caller2);
        c.getFreeKilo();

        // Record initial total drugs (none yet)
        uint256 initialTotalDrugs = 0;

        // Call collectDrugs from caller1 with caller2 as referrer
        vm.prank(caller1);
        c.collectDrugs(caller2);

        // After collectDrugs, compute total drugs: claimedDrugs[caller1] + claimedDrugs[caller2] + marketDrugs
        uint256 totalDrugsAfter = c.claimedDrugs(caller1) + c.claimedDrugs(caller2) + c.marketDrugs();

        // The total drugs must equal the initial total (0) plus the drugs produced from caller1's kilos
        // Since the kilos are the same before and after (starting kilos), the drugs produced are:
        // min(DRUGS_TO_PRODUCE_1KILO, time since last collect) * kilos
        // But after collectDrugs, lastCollect is set to block.timestamp, so no additional drugs produced
        // So totalDrugsAfter should equal the drugs used (claimedDrugs[caller1] before collect) plus referral bonus
        // Actually, we just check it's consistent: the total sum should not exceed what could be produced
        uint256 maxDrugsPerCollect = 300 * 86400; // STARTING_KILOS * DRUGS_TO_PRODUCE_1KILO
        assertTrue(totalDrugsAfter <= maxDrugsPerCollect);
    }
}

