pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address referrer, uint256 drugsInMarket, uint256 drugsForCaller, uint256 callerKilos, uint256 referrerClaimedBefore) public {
        // Bound inputs to avoid overflow and ensure meaningful state
        drugsInMarket = bound(drugsInMarket, 0, 1000000);
        drugsForCaller = bound(drugsForCaller, 0, 1000000);
        callerKilos = bound(callerKilos, 0, 100);
        referrerClaimedBefore = bound(referrerClaimedBefore, 0, 1000000);

        // Setup: seed market, fund caller, give caller some kilos, set referrer claimed before
        vm.deal(address(c), 1 ether); // enough balance for trades
        c.seedMarket(drugsInMarket);
        vm.assume(caller != address(0) && referrer != address(0) && caller != referrer);

        // Give caller some kilos directly (simulate earlier getFreeKilo or collect)
        // We manipulate state via public calls: use getFreeKilo for caller if not already
        vm.prank(caller);
        c.getFreeKilo(); // sets Kilos[caller] = STARTING_KILOS = 300
        // Override caller's kilos by setting via a custom approach: use collectDrugs to create drugs
        // Simpler: set caller's lastCollect to far past so getDrugsSinceLastCollect returns large
        // Actually, we can set claimedDrugs[caller] directly via buyDrugs
        // But to avoid complexity, we just rely on the fact that getMyDrugs returns claimedDrugs[caller] + drugsSinceLastCollect
        // Instead, we set claimedDrugs[caller] = drugsForCaller via buyDrugs with appropriate ETH
        // That is complex. Simpler: we just use the fact that getMyDrugs() will be drugsForCaller if we set claimedDrugs[caller] and lastCollect to now.
        // But lastCollect cannot be set directly. We'll use buyDrugs to add to claimedDrugs.
        // Skip: Instead, we test the rule by calling collectDrugs and checking referrer's claimedDrugs change is exactly getMyDrugs()/5.
        // We can compute expected change as getMyDrugs()/5 and compare to actual change.

        // Pre-state: record referrer's claimedDrugs before
        uint256 referrerBefore = c.claimedDrugs(referrer);

        // Call collectDrugs from caller with referrer
        vm.prank(caller);
        // To ensure getMyDrugs() returns a known value, we set lastCollect[caller] to block.timestamp - some time
        // Actually we cannot set lastCollect directly. But we can set claimedDrugs[caller] via buyDrugs
        // Let's instead manipulate with getFreeKilo already done, then we need to fast forward time
        // Simpler: we'll compute expected new drugs from time passage: Kilos[caller] = 300, secondsPassed = 1 => getMyDrugs() = claimedDrugs[caller] + 300
        // But claimedDrugs[caller] is 0 after getFreeKilo resets it? Actually getFreeKilo does not reset claimedDrugs.
        // This is getting messy. Alternative: we can just test that the mutation changes the ratio, and the rule is violated for any positive getMyDrugs().
        // So we can restrict to the case where getMyDrugs() > 0 (e.g., by buying drugs or waiting).
        // Simpler: we fund caller with ETH and call buyDrugs to set claimedDrugs[caller] positive.
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.buyDrugs{value: 0.1 ether}();

        // Now record getMyDrugs() for caller before collect
        uint256 drugsUsedBefore = c.getMyDrugs();
        vm.assume(drugsUsedBefore > 0); // ensure we have something to distribute

        // Record referrer's claimedDrugs before
        uint256 referrerBefore2 = c.claimedDrugs(referrer);

        // Call collectDrugs
        vm.prank(caller);
        c.collectDrugs(referrer);

        // After call, referrer's claimedDrugs should have increased by drugsUsedBefore / 5 (in reference)
        uint256 referrerAfter = c.claimedDrugs(referrer);
        uint256 expectedIncrease = drugsUsedBefore / 5;

        // Assert: The actual increase equals exactly expectedIncrease
        assertTrue(referrerAfter - referrerBefore2 == expectedIncrease, "Referral bonus not one-fifth");
    }
}

