pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr1, address addr2) public {
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);
        // Initialize contract
        c.seedMarket(1000);
        // Ensure both users have some kilos
        vm.prank(addr1);
        c.getFreeKilo();
        vm.prank(addr2);
        c.getFreeKilo();
        // Record marketDrugs before DrugDealer
        uint256 marketBefore = c.marketDrugs();
        // Record claimedDrugs for both addresses
        uint256 claim1Before = c.claimedDrugs(addr1);
        uint256 claim2Before = c.claimedDrugs(addr2);
        // Call DrugDealer (this is actually ceoAddress change, but it's the entry point where difference manifests)
        // The actual difference is in collectDrugs, but we need a function that touches the state
        // Since DrugDealer only changes ceoAddress, we need to trigger collectDrugs
        // Let's call collectDrugs from addr2 and use DrugDealer as the trigger for difference
        // Actually the difference is in collectDrugs itself; we need to compare after a collectDrugs call
        // Re-do: Use collectDrugs as the function that differs between P and M
        vm.prank(addr1);
        c.collectDrugs(addr2);
        // Read state after collectDrugs
        uint256 marketAfter = c.marketDrugs();
        uint256 claim1After = c.claimedDrugs(addr1);
        uint256 claim2After = c.claimedDrugs(addr2);
        // Sum of marketDrugs + claimedDrugs for both addresses should be unchanged
        uint256 sumBefore = marketBefore + claim1Before + claim2Before;
        uint256 sumAfter = marketAfter + claim1After + claim2After;
        assertTrue(sumBefore == sumAfter, "Total drugs should be conserved");
    }
}

