pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref) public {
        vm.assume(caller != address(0) && caller != address(this));
        vm.assume(ref != address(0) && ref != caller);

        // Seed market to initialize the contract
        c.seedMarket(100 ether);

        // Get free kilos for the caller
        vm.prank(caller);
        c.getFreeKilo();

        // Record the timestamp before calling DrugDealer
        uint256 timestampBefore = block.timestamp;

        // Prank as actual deployed address for DrugDealer call (since it requires msg.sender == ceoAddress)
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        c.DrugDealer();

        uint256 timestampAfter = block.timestamp;

        // The rule: after DrugDealer, lastCollect[caller] must have been updated to block.timestamp
